'use strict';

function generateRobotsTxt({ origin, siteName, sitemapUrl }) {
  return [
    '# robots.txt generated by SEO Doctor — https://github.com/ZainHanif-3',
    `# Site: ${siteName || origin}`,
    '',
    'User-agent: *',
    'Allow: /',
    '',
    `Sitemap: ${sitemapUrl || origin + '/sitemap.xml'}`,
    ''
  ].join('\n');
}

function augmentRobotsTxt(existingText, sitemapUrl) {
  const text = String(existingText || '').replace(/\s+$/, '');
  if (/^sitemap\s*:/im.test(text)) return null;
  return `${text}\n\n# Added by SEO Doctor\nSitemap: ${sitemapUrl}\n`;
}

function generateSitemapXml(entries) {
  const urls = entries.filter(e => e && e.loc);
  const body = urls.map(e => [
    '  <url>',
    `    <loc>${escapeXml(e.loc)}</loc>`,
    e.lastmod ? `    <lastmod>${escapeXml(e.lastmod)}</lastmod>` : '',
    e.priority ? `    <priority>${escapeXml(e.priority)}</priority>` : '',
    '  </url>'
  ].filter(Boolean).join('\n')).join('\n');
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
    body,
    '</urlset>',
    ''
  ].join('\n');
}

function escapeXml(s) {
  return String(s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}

function sitemapEntriesFor(crawl) {
  const seen = new Set();
  const out = [];
  const push = (loc, lastmod) => {
    if (!loc || seen.has(loc)) return;
    seen.add(loc);
    out.push({
      loc,
      lastmod: (lastmod || new Date().toISOString()).slice(0, 10),
      priority: loc === crawl.startUrl ? '1.0' : '0.7'
    });
  };
  push(crawl.startUrl, null);
  for (const p of crawl.pages) {
    if (p.offsite) continue;
    if (p.status >= 200 && p.status < 300) push(p.finalUrl || p.url, p.fetchedAt);
  }
  return out;
}

module.exports = { generateRobotsTxt, augmentRobotsTxt, generateSitemapXml, sitemapEntriesFor };
